import { existsSync, readFileSync } from "node:fs";
import { isAbsolute, join, resolve } from "node:path";
import { spawn } from "node:child_process";

//#region src/subpath/testing/cli/entry.ts
const resolveCliEntry = (options) => {
	const packageRoot = resolve(options.packageRoot ?? process.cwd());
	const configured = options.bin ?? manifestBin(packageRoot, options.binName);
	if (typeof configured !== "string" || !configured.length) throw new TypeError("CLI bin path must be a non-empty string.");
	const entry = isAbsolute(configured) ? configured : resolve(packageRoot, configured);
	if (!existsSync(entry)) throw new Error(`CLI bin entry does not exist: ${entry}`);
	return entry;
};
const manifestBin = (packageRoot, binName) => {
	const manifestPath = join(packageRoot, "package.json");
	const manifest = parseManifest(manifestPath);
	if (typeof manifest.bin === "string") return manifest.bin;
	if (!manifest.bin || !Object.keys(manifest.bin).length) throw new Error(`Package manifest does not declare a bin entry: ${manifestPath}`);
	if (binName) {
		const entry = manifest.bin[binName];
		if (entry) return entry;
		throw new Error(`Package manifest does not declare bin "${binName}".`);
	}
	const entries = Object.entries(manifest.bin);
	if (entries.length === 1) return entries[0][1];
	throw new Error(`Package manifest declares multiple bins (${entries.map(([name]) => name).join(", ")}); provide binName.`);
};
const parseManifest = (path) => {
	const value = JSON.parse(readFileSync(path, "utf8"));
	if (!value || typeof value !== "object") throw new TypeError(`Package manifest must contain an object: ${path}`);
	const bin = Reflect.get(value, "bin");
	if (bin === void 0 || typeof bin === "string") return { bin };
	if (typeof bin === "object" && bin !== null) {
		const entries = Object.entries(bin);
		const normalized = {};
		for (const [name, entry] of entries) {
			if (typeof entry !== "string" || !entry.length) throw new TypeError(`Package manifest bin must be a string or string record: ${path}`);
			normalized[name] = entry;
		}
		return { bin: normalized };
	}
	throw new TypeError(`Package manifest bin must be a string or string record: ${path}`);
};

//#endregion
//#region src/subpath/testing/cli/index.ts
var ChildProcessCliRunner = class {
	entry;
	constructor(entry) {
		this.entry = entry;
	}
	run(argv = [], options = {}) {
		assertArgv(argv);
		assertTimeout(options.timeoutMs);
		return new Promise((resolve) => {
			const stderr = [];
			const stdout = [];
			const child = spawn(process.execPath, [this.entry, ...argv], {
				cwd: options.cwd,
				env: options.env ?? {},
				signal: options.signal,
				stdio: "pipe"
			});
			let error;
			let timedOut = false;
			const timeout = options.timeoutMs ? setTimeout(() => {
				timedOut = true;
				child.kill("SIGTERM");
			}, options.timeoutMs) : void 0;
			child.stdout.on("data", (chunk) => stdout.push(Buffer.from(chunk)));
			child.stderr.on("data", (chunk) => stderr.push(Buffer.from(chunk)));
			child.stdin.on("error", () => {});
			child.once("error", (cause) => {
				error = cause;
			});
			child.once("close", (exitCode, signal) => {
				if (timeout) clearTimeout(timeout);
				resolve({
					error,
					exitCode,
					signal,
					stderr: Buffer.concat(stderr).toString("utf8"),
					stdout: Buffer.concat(stdout).toString("utf8"),
					timedOut
				});
			});
			child.stdin.end(options.stdin);
		});
	}
};
const createCliRunner = (options = {}) => new ChildProcessCliRunner(resolveCliEntry(options));
const assertArgv = (argv) => {
	if (Array.isArray(argv) && argv.every((value) => typeof value === "string")) return;
	throw new TypeError("CLI argv must be an array of strings.");
};
const assertTimeout = (timeoutMs) => {
	if (timeoutMs === void 0) return;
	if (Number.isSafeInteger(timeoutMs) && timeoutMs > 0) return;
	throw new TypeError("CLI timeoutMs must be a positive integer.");
};

//#endregion
export { createCliRunner };